async function rebuildAffectedDays(days:number[]){if(!routePlanningResult)return;clearFoodSuggestions(days);const affected=new Set(days);routePlanningResult.days.forEach(day=>{if(affected.has(day.day))day.isUpdating=true;});render();refreshMap();for(const dayNumber of affected){const index=routePlanningResult.days.findIndex(day=>day.day===dayNumber);const current=routePlanningResult.days[index];if(!current)continue;try{routePlanningResult.days[index]=await rebuildManualDay(dayNumber,current.orderedPlaceIds,places,planningCity,resolveAmapRoute);}catch{routePlanningResult.days[index]={...current,isUpdating:false,warnings:[...current.warnings,"路线暂时无法获取。"]};}}routePlanningResult.days.forEach(day=>day.isUpdating=false);routePlanningResult.warnings=routePlanningResult.days.flatMap(day=>day.warnings);render();refreshMap();}
