function renderSettings(){const p=prefs(), done=!!routePlanningResult&&!routeStale;settings.innerHTML=done&&!settingsExpanded?`<div class="settings-title">行程设置 <button id="edit-settings">修改</button></div><p class="settings-summary">📍 ${esc(city.value||"未设置")} · 🗓 ${p.tripDays?`${p.tripDays}天${p.tripNights?`${p.tripNights}晚`:""}`:"自动建议"} · ☕ ${({vacation:"度假",relaxed:"轻松",flexible:"随便",compact:"紧凑",intense:"特种兵"})[p.pace]}</p>`:`<div class="settings-title">行程设置</div><div class="settings-grid"><label>目的地<input id="settings-city" value="${esc(city.value)}" /></label><label>行程时长<select id="trip-days"><option value="auto">随便</option>${[1,2,3,4,5].map(d=>`<option value="${d}" ${p.tripDays===d?"selected":""}>${d===1?"1天":`${d}天${d-1}晚`}</option>`).join("")}</select></label></div><small>随便：根据地点数量和停留时长自动建议</small><p class="setting-label">旅行节奏</p><div class="pace-picker">${([['vacation','度假'],['relaxed','轻松'],['flexible','随便'],['compact','紧凑'],['intense','特种兵']] as const).map(([k,l])=>`<button data-pace="${k}" class="${p.pace===k?"active":""}">${l}</button>`).join("")}</div><p class="pace-help">${({vacation:"少排一点，给休息和临时探索留空间。",relaxed:"行程偏松，不追求打卡数量。",flexible:"在地点数量和松弛感之间保持平衡。",compact:"尽量多排地点，但避免明显折返。",intense:"优先多打卡，接受更紧凑的安排。"})[p.pace]}</p><button id="generate-plan" class="generate-button">${routePlanningResult?"重新生成":"生成行程"}</button>`;$<HTMLButtonElement>("#edit-settings")?.addEventListener("click",()=>{settingsExpanded=true;render()});$<HTMLInputElement>("#settings-city")?.addEventListener("change",e=>{city.value=(e.target as HTMLInputElement).value;planningCity=city.value.trim();stale()});$<HTMLSelectElement>("#trip-days")?.addEventListener("change",stale);document.querySelectorAll<HTMLButtonElement>("[data-pace]").forEach(b=>b.addEventListener("click",()=>{document.querySelectorAll("[data-pace]").forEach(x=>x.classList.remove("active"));b.classList.add("active");stale()}));$<HTMLButtonElement>("#generate-plan")?.addEventListener("click",()=>void generate());}
