  itinerary.innerHTML=`${routeStale?`<div class="stale-notice">● 地点或行程条件已变化<br><button id="stale-generate">重新生成</button></div>`:""}<section class="unassigned" data-drop-day="unassigned"><div class="unassigned-head"><strong>暂未安排 · ${pool.length}</strong><button id="open-manual-search">+ 添加地点</button></div>${pool.length?`<div class="unassigned-chips">${pool.map(place=>`<button draggable="true" class="unassigned-chip" data-drag-place="${place.id}">${typeIcon(place.type,place.category)} ${esc(place.rawName)}</button>`).join("")}</div>`:`<p>暂无地点，可搜索添加，或把某天地点拖到这里。</p>`}${manualSearchOpen?`<div class="manual-search"><input id="manual-query" placeholder="搜索真实地点" /><button id="manual-search-button">搜索</button>${manualSearchLoading?"<p>正在搜索高德地点…</p>":manualSearchResults.map(candidate=>`<div class="manual-result"><strong>${typeIcon(undefined,candidate.poiType)} ${esc(candidate.name)}</strong><span>${esc([candidate.poiType,candidate.address].filter(Boolean).join(" · "))}</span><button data-add-poi="${candidate.poiId}">加入</button></div>`).join("")}</div>`:""}</section>${routePlanningResult.days.map(day=>dayCard(day)).join("")}${stayModuleMarkup()}`;
  $<HTMLButtonElement>("#stale-generate")?.addEventListener("click",()=>void generate());
  $<HTMLButtonElement>("#open-manual-search")?.addEventListener("click",()=>{manualSearchOpen=!manualSearchOpen;render();});
