  document.querySelectorAll<HTMLButtonElement>("[data-day]").forEach(b=>b.onclick=()=>{const d=Number(b.dataset.day);selectedDay=selectedDay===d?undefined:d;if(selectedDay)expandedDays.add(d);render();refreshMap(selectedDay);if(selectedDay===1)checkpoint("day_1_selected");else if(selectedDay===2)checkpoint("day_2_selected");});
