  document.querySelectorAll<HTMLButtonElement>("[data-guide-more]").forEach(b=>b.onclick=()=>{const id=b.dataset.guideMore!;expandedGuidePlaceIds.has(id)?expandedGuidePlaceIds.delete(id):expandedGuidePlaceIds.add(id);render();});
  document.querySelectorAll<HTMLButtonElement>("[data-open-food]").forEach(button=>button.onclick=()=>{const [day,index]=button.dataset.openFood!.split(":").map(Number);void openAlongRouteFood(day,index);});
