  document.querySelectorAll<HTMLButtonElement>("[data-add-food-here]").forEach(button=>button.onclick=()=>{const [key,index]=button.dataset.addFoodHere!.split("#");const candidate=foodSuggestionStates.get(key)?.candidates[Number(index)], [day,segmentIndex]=key.split(":").map(Number);if(candidate)addFoodCandidate(candidate,day,segmentIndex+1);});
  document.querySelectorAll<HTMLButtonElement>("[data-add-food-unassigned]").forEach(button=>button.onclick=()=>{const [key,index]=button.dataset.addFoodUnassigned!.split("#");const candidate=foodSuggestionStates.get(key)?.candidates[Number(index)];if(candidate)addFoodCandidate(candidate);});
