const expandedDays=new Set<number>(),expandedGuidePlaceIds=new Set<string>();
function foodSuggestionMarkup(day:number,index:number,segment:DayRoute["segments"][number]|undefined){
  if(!segment||segment.status!=="resolved"||segment.durationMinutes===null||segment.durationMinutes<15||segment.path.length<3)return "";
  const endpointPlaces=[segment.fromPlaceId,segment.toPlaceId].map(id=>places.find(place=>place.id===id)).filter((place):place is Place=>Boolean(place));
  if(endpointPlaces.some(place=>getPlaceVisual({type:place.type,category:place.category})==="eat"))return "";
  const key=foodSuggestionKey(day,index),state=foodSuggestionStates.get(key);
  if(!state)return `<div class="food-suggestion" data-food-precheck="${key}">正在看看附近有没有适合顺路吃的…</div>`;
  if(state.status==="checking")return `<div class="food-suggestion">正在看看附近有没有适合顺路吃的…</div>`;
  if(state.status==="failed")return `<div class="food-suggestion muted">附近餐厅暂未获取</div>`;
  if(state.status==="empty")return `<div class="food-suggestion muted">这段路附近暂时没有适合顺路加入的餐厅</div>`;
  if(state.status==="available")return `<div class="food-suggestion"><button data-open-food="${key}">◒ 路上找吃的</button></div>`;
  if(state.status==="loading")return `<div class="food-suggestion">正在计算顺路程度…</div>`;
  return `<div class="food-suggestion food-options"><p>顺路吃点什么</p>${state.candidates.map((candidate,index)=>`<div class="food-option"><div><strong>◒ ${esc(candidate.name)}</strong><span>${esc([candidate.category,candidate.rating?`${candidate.rating}分`:"",candidate.cost].filter(Boolean).join(" · "))}</span>${candidate.detourMinutes!==undefined?`<em>额外约 ${mins(candidate.detourMinutes)}</em>`:""}</div><div><button data-add-food-here="${key}#${index}">加到这里</button><button class="quiet" data-add-food-unassigned="${key}#${index}">暂不安排</button></div></div>`).join("")}</div>`;
}
function stayModuleMarkup(){
  if(stayState.status==="loading")return `<section class="stay-module"><p class="stay-kicker">🛏 还没决定住哪？</p><strong>正在根据当前多日路线确认住宿区域…</strong><small>先找真实交通锚点，再验证每天的首尾通勤。</small></section>`;
  if(stayState.status==="error")return `<section class="stay-module"><p class="stay-kicker">🛏 还没决定住哪？</p><strong>住宿区域暂未获取</strong><button data-stay-recommend>重新推荐</button></section>`;
  if(stayState.status!=="ready")return `<section class="stay-module"><p class="stay-kicker">🛏 还没决定住哪？</p><strong>根据你这几天的路线，找几个整体比较方便的住宿区域。</strong><button data-stay-recommend>推荐住宿</button></section>`;
  return `<section class="stay-module"><div class="stay-module-head"><div><p class="stay-kicker">🛏 住宿区域建议</p>${stayState.stale?`<small class="stay-stale">行程已调整，住宿建议可能需要更新。</small>`:""}</div><button data-stay-recommend>重新推荐</button></div>${selectedHotel?`<div class="selected-hotel">🛏 已选住宿：<strong>${esc(selectedHotel.name??selectedHotel.rawName)}</strong></div>`:""}${stayState.areas.length?stayState.areas.map(stayAreaCard).join(""):`<p class="stay-empty">暂时没有足够的真实交通数据生成区域建议。</p>`}</section>`;
}
function stayAreaCard(area:StayAreaCandidate){const selected=area.anchorPoiId===selectedStayAreaId,hotelLines=area.hotels?.map((hotel,index)=>`<div class="hotel-option"><div><strong>▣ ${esc(hotel.name)}</strong><span>${[hotel.rating?`${hotel.rating} 分`:"",`距地铁站 ${hotel.distanceToAnchorMeters}m`].filter(Boolean).join(" · ")}</span>${hotel.cost?`<em>参考消费：${esc(hotel.cost)}</em>`:""}</div><button data-select-hotel="${area.anchorPoiId}:${index}">选为住宿</button></div>`).join("")??"";return `<article class="stay-area-card ${selected?"selected":""}" data-stay-area="${area.anchorPoiId}"><button class="stay-area-focus" data-focus-stay="${area.anchorPoiId}"><strong>🛏 ${esc(area.anchorName)}</strong><span>${esc(area.explanation)}</span></button><div class="stay-days">${area.perDayCommuteMinutes.map(item=>`<span>Day ${item.day} 首尾约 ${item.minutes}min</span>`).join("")}</div><p>多日首尾通勤合计约 ${area.totalCommuteMinutes}min</p>${area.hotelStatus==="loading"?`<div class="stay-hotels-loading">正在搜索附近真实酒店…</div>`:area.hotelStatus==="ready"?`<div class="stay-hotels">${hotelLines||"<p>附近暂未找到合适酒店。</p>"}</div>`:`<button data-load-hotels="${area.anchorPoiId}">查看酒店</button>`}</article>`;}
async function generateStayRecommendations(){if(!routePlanningResult)return;stayState={...stayState,status:"loading",stale:false};render();try{const areas=await recommendStayAreas(routePlanningResult.days,places,planningCity);stayState={status:"ready",areas,stale:false,routeVersion:routePlanningResult.days.map(day=>`${day.day}:${day.orderedPlaceIds.join(",")}`).join("|")};selectedStayAreaId=areas[0]?.anchorPoiId;msg(areas.length?`已生成 ${areas.length} 个真实交通锚点周边的住宿建议。`:"暂未找到足够的真实住宿区域候选。",!areas.length);}catch{stayState={...stayState,status:"error",stale:true};msg("住宿区域生成失败，请稍后重试。",true);}render();refreshMap();}
async function loadStayHotels(anchorPoiId:string){const area=stayState.areas.find(item=>item.anchorPoiId===anchorPoiId);if(!area||area.hotelStatus==="loading"||area.hotelStatus==="ready")return;area.hotelStatus="loading";render();try{area.hotels=await findHotelsNearStayArea(area,planningCity);area.hotelStatus="ready";}catch{area.hotelStatus="error";msg("附近酒店搜索失败，请稍后重试。",true);}render();}
function selectStayHotel(areaId:string,index:number){const area=stayState.areas.find(item=>item.anchorPoiId===areaId),hotel=area?.hotels?.[index];if(!area||!hotel)return;selectedHotel={id:`selected-hotel-${hotel.poiId}`,rawName:hotel.name,name:hotel.name,poiStatus:"resolved",poiId:hotel.poiId,address:hotel.address,longitude:hotel.longitude,latitude:hotel.latitude,category:hotel.category??"酒店",type:"hotel",source:"stay_recommendation",tips:[],evidence:[],estimatedDurationMinutes:null,durationSource:"unknown",recommendationScore:3,recommendationReason:`住宿推荐：${area.anchorName}`,mustVisit:false};selectedStayAreaId=areaId;render();refreshMap();msg(`${hotel.name} 已设为本次旅行的住宿，不会加入日程或暂未安排。`);}
function dayCard(d:DayRoute){const open=expandedDays.has(d.day),names=d.orderedPlaceIds.map(id=>places.find(p=>p.id===id)?.rawName??"地点"),summary=names.length>4?`${names.slice(0,3).join(" → ")} → +${names.length-3}`:names.join(" → "),over=d.totalActivityMinutes>480;return `<article class="day-card ${selectedDay===d.day?"selected-day":""}" data-drop-day="${d.day}" data-drop-index="${d.orderedPlaceIds.length}"><button class="day-head" data-day="${d.day}"><span class="day-dot day-${d.day}"></span><span>Day ${d.day}</span><small>${names.length} 个地点${d.orderSource==="manual"?" · 已手动调整":""}</small><b>${open?"收起":"查看详情"}</b></button><p class="day-metrics">${d.isUpdating?"正在更新路线…":`游玩 ${mins(d.totalActivityMinutes)} · 通勤 ${d.totalTransitMinutes===null?"部分未获取":mins(d.totalTransitMinutes)}`}</p>${over?"<p class=\"day-warning\">这一天可能偏赶</p>":""}${!open?(names.length?`<p class="day-order">${esc(summary)}</p>`:"<p class=\"day-order\">这一天暂时没有安排</p>"):`<div class="timeline">${d.orderedPlaceIds.map((id,i)=>{const p=places.find(x=>x.id===id)!,seg=d.segments[i-1],active=selectedPlaceId===id;return `${i?`<div class="timeline-segment ${seg?.status==="failed"?"failed":""}">↓ ${seg?.status==="failed"?"路线暂未获取":`${seg?.transportMode==="walking"?"步行":"公交 / 地铁"} ${mins(seg?.durationMinutes??null)}`}</div>${foodSuggestionMarkup(d.day,i-1,seg)}`:""}<div class="timeline-item" data-drop-day="${d.day}" data-drop-index="${i}" draggable="true" data-drag-place="${id}"><button class="timeline-stop ${active?"selected":""}" data-stop="${id}"><strong>⠿ ${typeIcon(p.type,p.category)} ${esc(p.rawName)}</strong><span>${typeLabel(p.type)} · ${mins(p.estimatedDurationMinutes??60)} · ${"★".repeat(p.recommendationScore)}</span></button>${active?`<div class="guide-details">${guideDetails(p)}</div>`:""}</div>`}).join("")}</div>`}${d.warnings.length?`<p class="day-warning">部分通勤路线暂未获取</p>`:""}</article>`}
function findRouteSegment(dayNumber:number,index:number){const day=routePlanningResult?.days.find(item=>item.day===dayNumber),segment=day?.segments[index];if(!day||!segment)return;const from=places.find(place=>place.id===segment.fromPlaceId),to=places.find(place=>place.id===segment.toPlaceId);return from&&to?{day,segment,from,to}:undefined;}
async function ensureAlongRouteFood(dayNumber:number,index:number){const found=findRouteSegment(dayNumber,index),key=foodSuggestionKey(dayNumber,index);if(!found||foodSuggestionStates.has(key))return;foodSuggestionStates.set(key,{status:"checking",candidates:[]});render();try{const candidates=await precheckAlongRouteFood(found.segment,planningCity);foodSuggestionStates.set(key,{status:candidates.length?"available":"empty",candidates});}catch{foodSuggestionStates.set(key,{status:"failed",candidates:[]});}render();}
async function openAlongRouteFood(dayNumber:number,index:number){const found=findRouteSegment(dayNumber,index),key=foodSuggestionKey(dayNumber,index);if(!found)return;foodSuggestionStates.set(key,{status:"loading",candidates:[]});render();try{const candidates=await rankAlongRouteFood(found.segment,found.from,found.to,planningCity);foodSuggestionStates.set(key,{status:candidates.length?"ready":"empty",candidates});}catch{foodSuggestionStates.set(key,{status:"failed",candidates:[]});}render();}
function addFoodCandidate(candidate:FoodCandidate,dayNumber?:number,insertIndex?:number){if(places.some(place=>place.poiId===candidate.poiId)){msg("这个地点已经在你的行程里了。",true);return;}const id=`food-${candidate.poiId}`;places.push({id,rawName:candidate.name,name:candidate.name,poiStatus:"resolved",poiId:candidate.poiId,address:candidate.address,longitude:candidate.longitude,latitude:candidate.latitude,category:candidate.category,source:"manual",tips:[],evidence:[],type:placeTypeFromVisual.eat,estimatedDurationMinutes:60,durationSource:"default",recommendationScore:3,recommendationReason:"路线中途手动添加餐饮",mustVisit:false,manualDayOverride:null});if(dayNumber!==undefined)moveToDay(id,dayNumber,insertIndex);else{unassignedPlaceIds.push(id);render();refreshMap();}msg(`${candidate.name} 已加入${dayNumber!==undefined?` Day ${dayNumber}`:"暂未安排"}。`);}
function renderPlaceSearch(){const slot=$<HTMLElement>("#place-manual-search");if(activeTab!=="places"){slot.innerHTML="";return;}slot.innerHTML=manualSearchOpen?`<div class="manual-search place-search"><input id="place-search-query" placeholder="搜索真实地点" /><button id="place-search-button">搜索</button>${manualSearchLoading?"<p>正在搜索高德地点…</p>":manualSearchResults.map(candidate=>`<div class="manual-result"><strong>${typeIcon(undefined,candidate.poiType)} ${esc(candidate.name)}</strong><span>${esc([candidate.poiType,candidate.address].filter(Boolean).join(" · "))}</span><button data-add-poi="${candidate.poiId}">加入</button></div>`).join("")}</div>`:"";const addButton=$<HTMLButtonElement>("#add-place-from-list");addButton.onclick=()=>{manualSearchOpen=!manualSearchOpen;render();};$<HTMLButtonElement>("#place-search-button")?.addEventListener("click",()=>void searchManual($<HTMLInputElement>("#place-search-query").value));slot.querySelectorAll<HTMLButtonElement>("[data-add-poi]").forEach(button=>button.onclick=()=>{const candidate=manualSearchResults.find(item=>item.poiId===button.dataset.addPoi);if(candidate)addManualPlace(candidate);});}
function removeFromTrip(placeId:string){const affected=routePlanningResult?.days.filter(day=>day.orderedPlaceIds.includes(placeId)).map(day=>day.day)??[];places=places.filter(place=>place.id!==placeId);unassignedPlaceIds=unassignedPlaceIds.filter(id=>id!==placeId);routePlanningResult?.days.forEach(day=>{day.orderedPlaceIds=day.orderedPlaceIds.filter(id=>id!==placeId);day.placeIds=[...day.orderedPlaceIds];});if(affected.length)void rebuildAffectedDays(affected);else{render();refreshMap();}}
function stopNestedDropBubbling(){document.querySelectorAll<HTMLElement>(".timeline-item[data-drop-day]").forEach(item=>item.addEventListener("drop",event=>event.stopPropagation()));}
function render(){workspace.hidden=!places.length;$<HTMLElement>("#place-count").textContent=String(places.length);$<HTMLElement>("#day-count").textContent=routePlanningResult?`${routePlanningResult.days.length}天`:"—";renderSettings();renderPlaces();renderPlaceSearch();renderItinerary();stopNestedDropBubbling();$<HTMLElement>("#places-view").hidden=activeTab!=="places";itinerary.hidden=activeTab!=="itinerary";$<HTMLElement>("#tab-places").classList.toggle("active",activeTab==="places");$<HTMLElement>("#tab-itinerary").classList.toggle("active",activeTab==="itinerary");}
function selectStop(id:string){selectedPlaceId=id;const p=places.find(x=>x.id===id),r=p&&resolved(p);if(r)mapView.focusPlace(r);render();refreshMap();}
function selectFromMap(id:string){selectedPlaceId=id;const d=routePlanningResult?.days.find(x=>x.orderedPlaceIds.includes(id));if(d){activeTab="itinerary";selectedDay=d.day;expandedDays.add(d.day);}render();checkpoint(d?.day===1?"day_1_selected":d?.day===2?"day_2_selected":"map_ready");setTimeout(()=>document.querySelector(`[data-stop="${CSS.escape(id)}"]`)?.scrollIntoView({block:"center",behavior:"smooth"}),0);}
async function ground(cityName:string){msg("正在确认地点……");const rs:{p:Place;r:Awaited<ReturnType<typeof resolvePlace>>}[]=[];for(const p of places){rs.push({p,r:await resolvePlace({city:cityName,name:p.rawName})});}places=rs.map(({p,r})=>r.status==="resolved"?{...p,...r,poiStatus:"resolved"}:r.status==="ambiguous"?{...p,poiStatus:"ambiguous",poiCandidates:r.candidates}:{...p,poiStatus:r.status});places=dedupeResolvedPlaces(places).places;render();refreshMap();msg(`${places.filter(p=>p.poiStatus==="resolved").length} 个地点已确认；其余地点可继续确认。`);checkpoint("pois_ready");checkpoint("map_ready");}
async function extract(){
  const text=notes.value.trim(), cityName=city.value.trim();
  if(!cityName){msg("先告诉我想去哪个城市。",true);city.focus();return;}
  if(!text&&!images.length){msg("粘贴一段攻略，或上传至少一张截图。",true);notes.focus();return;}
  isExtracting=true;syncInputUi();
  checkpoint("source_loaded");captureEvent("extract_requested",{city:cityName,hasText:!!text,imageCount:images.length});
  try{
    msg("正在从攻略里找你种草的地方……");checkpoint("ai_processing");
    const out=await extractPlaces(text,images),c=cityName;
    planningCity=c;city.value=c;places=out.places.map((p,i)=>({id:`${p.name}-${i}`,rawName:p.name,poiStatus:"unresolved",mustVisit:false,...p}));
    checkpoint("ai_extracted",{extraction:{city:out.city,places:out.places}});resetGuideSummaries();clearFoodSuggestions();stayState={status:"idle",areas:[],stale:false};selectedStayAreaId=undefined;selectedHotel=undefined;routePlanningResult=undefined;planningResult=undefined;routeStale=false;
    await ground(c);hasParseRecord=true;isInputExpanded=false;syncInputUi();
  }catch(e){msg(e instanceof Error?e.message:"攻略解析失败。",true);captureEvent("extract_failed",{message:status.textContent});
  }finally{isExtracting=false;syncInputUi();}
}
async function generate(){if(!planningCity){msg("请先确认目的地。",true);return;}const b=$<HTMLButtonElement>("#generate-plan");if(b)b.disabled=true;try{planningResult=groupPlaces(places,prefs());clearFoodSuggestions();markStayStale();msg("正在通过高德确认日内路线……");captureEvent("itinerary_requested",{planning:planningResult});routePlanningResult=await planRoutes(planningResult.groups,places,planningCity,resolveAmapRoute);routeStale=false;settingsExpanded=false;activeTab="itinerary";selectedDay=undefined;render();refreshMap();msg(routePlanningResult.warnings.length?"行程已生成，部分路线暂未获取。":"已生成真实高德行程。");checkpoint("itinerary_ready");if(guideSummaryStale)void buildGuideSummaries();}catch(e){msg(e instanceof Error?e.message:"行程生成失败。",true);captureEvent("itinerary_failed",{message:status.textContent});}finally{if(b)b.disabled=false}}
$<HTMLButtonElement>("#extract-button").onclick=()=>void extract();
