imageInput.onchange=async()=>{const fs=[...(imageInput.files??[])],add=fs.filter(f=>!imageKeys.has(`${f.name}-${f.size}-${f.lastModified}`));if(images.length+add.length>6||add.some(f=>f.size>5*1024*1024)){msg("最多上传 6 张图片，单张不超过 5MB。",true);return;}try{const data=await Promise.all(add.map(f=>new Promise<UploadedImage>((ok,no)=>{const r=new FileReader(),fileKey=`${f.name}-${f.size}-${f.lastModified}`;r.onload=()=>ok({id:crypto.randomUUID(),name:f.name,fileKey,mimeType:f.type,data:String(r.result).split(",")[1]});r.onerror=no;r.readAsDataURL(f)})));data.forEach(image=>imageKeys.add(image.fileKey));images.push(...data);try{captureImages.push(...add.map(f=>({name:f.name,mimeType:f.type,size:f.size})));captureEvent("source_images_loaded",{images:captureImages});}catch{/* capture must never affect image import */}renderImagePreviews();syncInputUi();}catch{msg("图片读取失败，请换一张图片再试。",true);}finally{imageInput.value="";}};
